require dirname(__DIR__).'/app/bootstrap.php';Auth::requireAdmin();$adminTitle='Manajemen Event';$id=(int)($_GET['edit']??0);$edit=null;if($id){$s=db()->prepare('SELECT * FROM events WHERE id=?');$s->execute([$id]);$edit=$s->fetch();}
