mepage_mode']??'')==='LEADERBOARD'?'selected':'' ?>>Prioritaskan Leaderboard</option></select></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="leaderboard_visible" <?= !isset($edit['leaderboard_visible'])||$edit['leaderboard_visible']?'checked':'' ?>><label class="form-check-label">Tampilkan leaderboard</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="leaderboard_frozen" <?= ($edit['leaderboard_frozen']??0)?'checked':'' ?>><label class="form-check-label">Bekukan tampilan publik</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="points_visible" <?= !isset($edit['points_visible'])||$edit['points_visible']?'checked':'' ?>><label class="form-check-label">Tampilkan persentase dukungan publik</label></div></div><div class="col-12 d-grid"><button class="btn btn-admin"><?= $edit?'Simpan Perubahan':'Tambah Event' ?></button></div><?php if($edit):?><div class="col-12 d-grid"><a class="btn btn-light" href="events.php">Batal Edit</a></div><?php endif;?></form></div></div><div class="col-xl-8"><div class="admin-card overflow-hidden"><div class="p-4"><h5 class="mb-0">Daftar Event</h5></div><div class="table-responsive"><table class="table table-admin"><thead><tr><th>Event</th><th>Periode Voting</th><th>Status</th><th>Leaderboard</th><th></th></tr></thead><tbody><?php foreach($events as $r):?><tr><td><strong><?= e($r['name']) ?></strong><small class="d-block text-secondary"><?= e($r['year']) ?> • <?= e($r['theme']) ?></small></td><td><small><?= indonesia_date($r['voting_start_at'],true) ?><br>s.d. <?= indonesia_date($r['voting_end_at'],true) ?></small></td><td><span class="badge <?= $r['status']==='VOTING_ACTIVE'?'text-bg-success':'text-bg-secondary' ?>"><?= e($r['status']) ?></span></td><td><?= $r['leaderboard_frozen']?'Dibekukan':'Real-time' ?></td><td class="text-end"><a class="btn btn-sm btn-outline-success" href="?edit=<?= (int)$r['id'] ?>">